// ─── File: VpcDemo.java ───
package com.bank.vpc;

import java.util.logging.*;

public class VpcDemo {
    private static final Logger log = Logger.getLogger("VPC");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Public subnet: route to the Internet Gateway.
        RouteTable publicRt = new RouteTable();
        publicRt.addRoute("10.0.0.0/16", "local");
        publicRt.addRoute("0.0.0.0/0", "igw-0abc123");
        Subnet lbSubnet = new Subnet("subnet-lb", "10.0.1.0/24", "ap-south-1a", publicRt);

        // Private subnet: outbound via NAT only.
        RouteTable privateRt = new RouteTable();
        privateRt.addRoute("10.0.0.0/16", "local");
        privateRt.addRoute("0.0.0.0/0", "nat-0xyz789");
        Subnet dbSubnet = new Subnet("subnet-db", "10.0.10.0/24", "ap-south-1a", privateRt);

        SubnetClassifier classifier = new SubnetClassifier();
        log.info(() -> "Load-balancer subnet is: " + classifier.classify(lbSubnet));
        log.info(() -> "Database subnet is: " + classifier.classify(dbSubnet));
        log.info(() -> "Usable IPs in a /24: " + Subnet.usableIps(24));
    }
}

// ─── Would be in RouteTable.java ───
class RouteTable {
    private final java.util.LinkedHashMap<String, String> routes = new java.util.LinkedHashMap<>();
    void addRoute(String cidr, String target) { routes.put(cidr, target); }
    String targetFor(String cidr) { return routes.get(cidr); }
}

// ─── Would be in Subnet.java ───
class Subnet {
    final String id, cidr, az; final RouteTable routeTable;
    Subnet(String id, String cidr, String az, RouteTable rt) {
        this.id = id; this.cidr = cidr; this.az = az; this.routeTable = rt;
    }
    static int usableIps(int prefix) { return (int) Math.pow(2, 32 - prefix) - 5; } // AWS reserves 5
}

// ─── Would be in SubnetClassifier.java ───
class SubnetClassifier {
    // The ONLY thing that makes a subnet public: a 0.0.0.0/0 route to an IGW.
    String classify(Subnet s) {
        String target = s.routeTable.targetFor("0.0.0.0/0");
        if (target != null && target.startsWith("igw-")) return "PUBLIC (route to Internet Gateway)";
        if (target != null && target.startsWith("nat-")) return "PRIVATE (outbound via NAT only)";
        return "PRIVATE (no internet route — fully isolated)";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
